// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":128,"question":"يتساهل كثيرٌ من الناس فيما يُسمَّى بالحق العامّ، فيستخدمون سيارات دائرات حكومية لأغراضٍ شخصيةٍ، أو الهاتف في العمل يتَّصلون منه على أقارب خارج المنطقة، أو غير ذلك، ما ضابط هذا؟ جزاكم الله خيرًا","title":"حكم استعمال المال العام في الأمور الخاصة","answer":"الجواب: الواجب على العامل والموظف أن يتَّقي الله، وأن لا يستعمل ما تحت يده إلا بما أباحته الدولة وأذنت فيه، فإذا كان الشيء الذي يفعله مباحًا له فلا بأس، وإلا فليحذر، وإذا شكَّ يتورع ويترك ما شكَّ فيه: دع ما يريبك إلى ما لا يريبك هكذا قال ﷺ، وقال أيضًا: مَن اتَّقى الشُّبهات فقد استبرأ لدينه وعرضه، وما كان معروفًا أنهم أجازوه فلا حرج في ذلك، وما منعوه وجب تركه؛ لأنَّ على كل مسلمٍ السمع والطاعة في المعروف، فما مُنِعَ على الموظف لا يأتيه، وما أُذِنَ له يأتيه، وما اشتبه عليه يدعه: دع ما يريبك إلى ما لا يريبك.","link":"https://binbaz.org.sa/fatwas/3635/حكم-استعمال-المال-العام-في-الامور-الخاصة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0117.mp3","categories":["أحكام الموظفين"]},{"id":136,"question":"بعض الموظفين يستغلُّون سلطتهم الوظيفية باستخدام الأفراد العسكريين أو الموظفين في إداراتهم لقضاء شؤونهم الخاصَّة المنزلية، وإنهاء مُعاملتهم الخاصَّة لدى الدوائر الحكومية، فما رأي سماحتكم؟","title":"حكم من يستخدم موظفيه في أموره الخاصة","answer":"الجواب: لا يجوز استخدامهم في الحاجات الأخرى إلا بطريقةٍ خاصةٍ بينه وبين الخادم في غير وقت العمل، فإذا تراضى هو والخادم في أوقاتٍ أخرى أنه يخدمه ويُعطيه ما يُرضيه ويُعينه فهذا شيءٌ إليه، أما وقت العمل فيكون خاصًّا بمحل العمل الحكومي، فيكون الخادم وغير الخادم يعملون في محلِّ العمل الحكومي الذي هم مأمورون به. وإذا كانت له حاجات يكون له خادمٌ آخر غير الخادم الذي للحكومة -خادم لحاجات البيت والحاجات الأخرى- يكون له خادمٌ آخر تبع البيت، تبع حاجاته هو، تبع ماله، يخصّه، وأما خادم الحكومة فيكون في عمل الحكومة، وإذا كان هذا الخادم يعمل خارج العمل في وقت الإجازة ووقت الراحة بشيءٍ بينه وبين رئيسه، لا يستغله لأنه خادم، بل بينه وبينه مساعدة، فيُعطيه مساعدةً باختياره ورضاه، لا بالوعيد ولا بالتهديد؛ فلا يضرّ هذا، أما بالوعيد أو بالتَّهديد إن لم يفعل فهذا لا يجوز.","link":"https://binbaz.org.sa/fatwas/3672/حكم-من-يستخدم-موظفيه-في-اموره-الخاصة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0128.mp3","categories":["أحكام الموظفين"]},{"id":142,"question":"يلجأ بعضُ أصحاب النفوس الضَّعيفة إلى إرسال شكاوى وبلاغات كيدية تحت اسم مستعار، أو بتوقيع: فاعل خير، ضدّ بعض المسؤولين أو غيرهم ممن هم أشدَّاء في إحقاق الحق، ولقد ورد في القرآن الكريم: يَا أَيُّهَا الَّذِينَ آمَنُوا إِنْ جَاءَكُمْ فَاسِقٌ بِنَبَإٍ فَتَبَيَّنُوا الآية [الحجرات:6]، والأوامر السامية التي تتفق وأحكام الشَّرع الحنيف لا تأخذ مثل هذه الدعاوى؛ لأنَّ أهدافها واضحة، ومقاصدها معلومة، فنرجو من سماحتكم إسداء النُّصح وإيضاح الجوانب الدينية في أمثال هذه الشكاوى المُذيَّلة باسم: فاعل خير، أو باسم مُستعار.","title":"ما حكم البلاغات الكيدية التي يوقّعها مجهول؟","answer":"الجواب: الأصل أنَّ مَن لم يُسمّ نفسه لا تُقبل شهادته، ولا يُقبل قوله؛ لأنه قد يكون فاسقًا، وقد يكون ذا قصد سيئ، وقد سمعت الآية: إِنْ جَاءَكُمْ فَاسِقٌ بِنَبَإٍ فَتَبَيَّنُوا، فلا يُعتمد عليه إذا قال: فلان فعل كذا، أو: فلان قال كذا، أو: فلان ترك كذا، لا يُعتمد عليه حتى يُبين نفسه، ويشهد، وتثبت البينة الشرعية في حقِّ الشخص.\nلكن إذا كان مَن كتب النصيحة ناصحًا أو فاعل خيرٍ يُخبر عن عملٍ وقع في المؤسسة، أو وقع في المكتب، فالواجب على مدير المكتب الذي كتب إليه أن ينظر في الأمر؛ لأنَّ هذا الكاتب قد يكون كما قال ناصحًا، ولكن لو سُمِّي لأوذي، فإذا كان يقول: المكتب وقع فيه كذا، أو: الدائرة الفلانية فيها كذا وكذا، فالواجب على المكتوب إليه أن ينظر في الأمر: هل هو صحيح؟ يقول لك فاعل خير: الموظفون في مكتبك ما يُصلون، ما يقومون بالعمل، يُؤذون المراجعين، اتَّقِ الله، حاسبهم، انظر الأمر: هل هو صادقٌ؟ ولا تحتجّ بمجرد أنه ما سمَّى نفسه وتُهمل، لا، لو سمَّى نفسه ربما آذيتُموه وآذى المكتوب إليه، فقد يكون موظفًا أيضًا.\nفإذا كان الكاتبُ -الذي ما سمَّى نفسه- ناصحًا يريد من المسؤول أن ينظر في الأمر، ما قال: فلان ابن فلان، يُقال: انظروا مكتبكم فيه كذا وكذا، دائرتكم فيها كذا وكذا، فالواجب عليك أيها المسؤول -من مدير المكتب أو عميد المكتب أو كذا- أن تنظر فيمَن نُسب إليهم الأمر، فالذي يُقال أنَّهم ما يُصلون ينظر فيهم، يدخنون ينظر فيهم، يُهملون القضايا والرسائل ينظر فيهم، يُؤذون المُراجعين ويسبونهم ينظر فيهم، ولا تحتج بأنه ما سمَّى نفسه وفقط، اتَّقِ الله وانظر فيما قال لك ونصحك فيه، ولو ما سمَّى نفسه، أما إذا قال: فلان يعمل كذا، وسمَّى واحدًا مُعينًا؛ فلا تُطعه فيه حتى تنظر في الأمر وتعرف هل هو صادق أم غير صادقٍ فيه؟ يقول: فلان ما يُصلي، وهو عندك في المكتب، انظر فيه هل هو يُصلي أم لا يُصلي؟ وَصِّ عليه الناسَ الذين عندك: انظروا هل هو يُصلي أم لا يُصلي؟ هو يدخن أو ما يُدخن؟ وأنتم ممنوعون في الإدارة من التَّدخين، انظروا ماذا قال، ولا تعتمده، اعمل الأسباب الأخرى أنت، وأما اتِّخاذها تَكِئَةً -أنه ما سمَّى نفسه- حتى تُضيع الأمر، فلا، هذا غلطٌ.","link":"https://binbaz.org.sa/fatwas/3679/ما-حكم-البلاغات-الكيدية-التي-يوقعها-مجهول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0135.mp3","categories":["أحكام الموظفين"]},{"id":264,"question":"أنا مسؤولٌ عن الصرف المباشر في إحدى الجهات الحكومية، فهل إذا عمدني رئيسي بصرف شيءٍ مخالفٍ لتعليمات الدولة أكون قد خنتُ الأمانة؟ أجيبونا أثابكم الله.","title":"حكم طاعة رئيس العمل بخلاف أوامر الدولة","answer":"الجواب: نعم، إذا عمدك رئيسك بما يُخالف أمر الدولة، وأعظم من ذلك أن يُخالف أمر الله، فأنت بذلك تكون عاصيًا؛ لأنَّ الطاعة إنما تكون في المعروف، يقول الله لنبيه: وَلَا يَعْصِينَكَ فِي مَعْرُوفٍ [الممتحنة:12]، مع أنَّه لا يأمر إلا بالمعروف عليه الصلاة والسلام، ويقول النبيُّ ﷺ: إنما الطاعة في المعروف، فإذا عاونت رئيسك على السرقة والرشوة وتعاطي الحرام فأنت شريكه في الإثم، وإذا عاونت رئيسك على خيانة الدولة ومخالفة أوامرها لحظِّكم ولأهوائكم فأنت شريكٌ له في الإثم.\nوالواجب التعاون على طاعة الله ورسوله، وعلى طاعة الدولة في المعروف، كما سمعت الله يقول: يَا أَيُّهَا الَّذِينَ آمَنُوا أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ وَأُولِي الْأَمْرِ مِنْكُمْ [النساء:59]، فطاعة أولي الأمر واجبةٌ في طاعة الله ورسوله في المعروف، فليس لأحدٍ أن يُطيع أميره أو رئيسه أو زوجته أو الزوجة لزوجها أو الأب أو الأم في معصية الله ورسوله، ليس لهم طاعةٌ في ذلك بعد أن تعلم أنَّ ما أمروا به معصية لله ولرسوله، تكون على بينةٍ؛ لأنَّ الرسول عليه الصلاة والسلام قال: لا طاعة لمخلوقٍ في معصية الخالق.\nفإذا قالت الزوجةُ لزوجها: أبغي كذا وكذا، فيما حرَّم الله، أو قال الأبُ لولده: أحضر كذا وكذا، مما حرَّم الله من خمورٍ، أو تدخين، أو ما أشبه ذلك، أو آلات لهوٍ، أو ما أشبه ذلك؛ لم يُطعهم في معصية الله  وهكذا بقية المعاصي، فليس للزوج أن يُطيع الزوجة، وليس للزوجة أن تُطيع الزوج، كأن يطلب منها أن يُجامعها في الدبر، أو في الحيض، أو في النفاس، هذا منكرٌ، وليس لها طاعته في ذلك، بل عليها أن تأبى عن ذلك بكل قوةٍ، هكذا إذا أراد منها أن تشرب المُسكر معه، هذا أيضًا منكرٌ، وليس لها طاعته في ذلك، أو أمرها أن تجلس عند إخوانه وأعمامه بالسُّفور وعدم الحجاب، لا تُطعه في ذلك؛ لأنَّ هذا من أسباب الفتنة، ولأنه معصيةٌ لله، فليس له أن يأمرها بذلك، وليس لها أن تُطيعه فيما حرَّم الله عليها، وما يُسبب الشرَّ عليها، وهكذا ليس له طاعتها هي، ليس له أن يُطيعها فيما حرَّم الله، في أي شيءٍ مما حرَّم الله.\nوهكذا ليس للموظف أن يُطيع رئيسه في محارم الله، ولا يتعاون معه في رشوةٍ، أو خيانةٍ، كل ذلك ممنوعٌ ومنكرٌ.","link":"https://binbaz.org.sa/fatwas/4258/حكم-طاعة-رىيس-العمل-بخلاف-اوامر-الدولة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0309.mp3","categories":["أحكام الموظفين"]},{"id":266,"question":"ما حكم مَن يخون الأمانة في صالح الإسلام والمسلمين؟","title":"حكم خيانة الأمانة لصالح الإسلام والمسلمين","answer":"الجواب: لا يُسمَّى هذا خائنًا، الذي يعمل في صالح الإسلام والمسلمين ما يُسمَّى خائنًا للأمانة، يُسمَّى مُؤدِّي الأمانة، فأداء الأمانة يكون في صالح الإسلام والمسلمين، وأما الخيانة فلا تكون في صالح الإسلام والمسلمين، الخيانة خيانة على اسمها شرٌّ، لكن إذا كان عملًا في صالح الإسلام والمسلمين فهو ليس بخيانةٍ.\nولكن ما هو هذا العمل الذي ظنَّه صاحبُه خيانةً؟\nفالرشوة ليست في صالح الإسلام والمسلمين، وعصيان ولاة الأمور ليس في صالح الإسلام والمسلمين، فلا بدّ من النظر في هذا الأمر، فإن كان الإنسان مأمورًا بمعصية الله، فلا يفعل معصية الله؛ لأنه لا تجوز له الطاعة في معصيته، وإذا كان هذا قصده فإنَّ هذا ما يُسمَّى خيانة، بل هذا أداء للأمانة، وأنه لا يُطيع في المعصية هذا مُقتضى الأمانة، ألا يعصي الله؛ لأنَّ الأمانة عليه أن يُطيع الله، فإذا لم يُجب للمعصية فقد أدَّى الأمانة، ما يُسمَّى خائنًا للأمانة.","link":"https://binbaz.org.sa/fatwas/4262/حكم-خيانة-الامانة-لصالح-الاسلام-والمسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0311.mp3","categories":["أحكام الموظفين"]},{"id":268,"question":"سائلٌ يسأل فيقول: سماحة الشيخ ابن باز وفَّقه الله، أنا موظفٌ في البريد، وفي بعض الأحيان تأتي ظروفٌ توجد فيها أشرطة غنائية وصور خليعة، فهل هذه أمانة لا بدّ لي من إيصالها أم أقوم بإتلافها دون علم المسؤول، ودون علم صاحب الرسالة؟ أفيدونا جزاكم الله خيرًا.","title":"ما حكم رسائل البريد التي بها منكرات؟","answer":"هذا هو المثال الذي ينبغي أن يُذكر، مثل هذا ليس إتلافه من الخيانة، بل هو من الأمانة، فإذا عرفت أنَّ هذا الظرف فيه ما حرَّم الله والدَّعوة إلى ما حرَّم الله فالواجب إتلافه، إتلاف ما فيه من الأشرطة الفاسدة التي تدعو إلى الباطل، والصور الفاسدة التي تدعو إلى الباطل، من غير حاجةٍ إلى استئذان المسؤول، إذا عرفتَ هذا وتبصَّرتَ فيه فإنَّ الواجب إتلافه؛ لأنَّ هذا من باب إنكار المنكر، وإيصاله إلى صاحبه من الخيانة، لا من الأمانة.","link":"https://binbaz.org.sa/fatwas/4264/ما-حكم-رساىل-البريد-التي-بها-منكرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0313.mp3","categories":["أحكام الموظفين"]},{"id":452,"question":"إذا كان الموظف لا يعطيني حقي إلا بالرشوة؟","title":"ما حكم الرشوة لموظفٍ لا ينجز إلا بها؟","answer":"الجواب: افضحه وارفع أمره للمسؤول أن هذا ما يعطيني حقي إلا بالرشوة، ولا تتساهل معه.\n(دروس شرح بلوغ المرام، كتاب البيوع)","link":"https://binbaz.org.sa/fatwas/6175/ما-حكم-الرشوة-لموظف-لا-ينجز-الا-بها","audio":"https://files.zadapps.info/binbaz.org.sa/reshwa010.mp3","categories":["الكسب المحرم","أحكام الموظفين"]},{"id":454,"question":"إحدى النساء خصصت أن تأخذ مبلغًا قدره خمسة آلاف ريال مقابل التعيين في المنطقة التي تحتاجها؟","title":"حكم تقاضي الموظف أموالًا لتقديم خدمات","answer":"الجواب: هذا من الشفاعة، وهذا من الاعتداء، وهذا من المُحَرَّم، الواجب عليها أن تعمل بمقتضى التعليمات بدون رشوة.\n(دروس شرح بلوغ المرام، كتاب البيوع)","link":"https://binbaz.org.sa/fatwas/6178/حكم-تقاضي-الموظف-اموالا-لتقديم-خدمات","audio":"https://files.zadapps.info/binbaz.org.sa/sho3'l013.mp3","categories":["الكسب المحرم","أحكام الموظفين"]},{"id":1159,"question":"ما حكم استعمال الهاتف في مقرِّ العمل للمصالح الشَّخصية، مثل: أن يتصل الشخصُ ببيته، أو لقضاء مصلحةٍ تخصُّه لوحده؟ مع العلم أنَّ الرئيس أو المسؤول في العمل يسمح بذلك.","title":"ما حكم استعمال هاتف العمل لأمور شخصية؟","answer":"الجواب:\nلا نعلم في هذا بأسًا إن شاء الله إذا كان قليلًا ودعت إليه الحاجةُ، نرجو ألا حرج في ذلك، لا ينبغي التَّشديد في هذا، نرجو ألا حرج في ذلك إن شاء الله، نحن نستعمله وغيرنا.","link":"https://binbaz.org.sa/fatwas/21224/ما-حكم-استعمال-هاتف-العمل-لامور-شخصية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1020ما حكم استعمال هاتف العمل للأغراض الشخصية؟ ابن ابز.mp3","categories":["أحكام الموظفين"]},{"id":2289,"question":"ما ضابط الإمارة؟ مدير الشرطة مثلًا أو مدير شركة أو يجب أن يكون مثلاً أمير ؟","title":"ما ضابط الإمارة؟ وفيم تكون؟","answer":"الجواب:\nالإمارة على البلد أو القرية أو القبيلة، هذه هي الإمارات، أمَّا هذه فوظائف، والنبي ﷺ لما قال له عثمانُ بن أبي العاص: اجعلني إمامَ قومي، قال: أنت إمامهم، وما أنكر عليه سؤال الإمامة، فكونه يسأل أن يكون في محلِّ كذا -موظف في الهيئة أو في شرطة البلد الفلانية أو قوة الأمير الفلاني- لا بأس به؛ لأنَّ الناس يحتاجون لهذه الأشياء، والمسؤول هو الأمير.","link":"https://binbaz.org.sa/fatwas/22412/ما-ضابط-الامارة-وفيم-تكون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ضابط الإمارة.mp3","categories":["أحكام الموظفين"]},{"id":2291,"question":"ألا يُستثنى من ذلك الكُفْءُ كما حصل ليوسف عليه السلام؟ فإذا كان الإنسانُ كفؤًا ويرى من نفسه أنه يستطيع ..؟","title":"ما حكم طلب الكُفْء الإمارة؟","answer":"الجواب:\nهذا قد يقع، وإذا وقع فلا مانع منه؛ لقوله ﷺ لمن قال: اجعلني إمامَ قومي، قال: أنت إمامهم، ولقوله جلَّ وعلا في قصة يوسف: قَالَ اجْعَلْنِي عَلَى خَزَائِنِ الْأَرْضِ إِنِّي حَفِيظٌ عَلِيمٌ [يوسف:55] لما رأى يوسف من نفسه القوةَ على هذا الأمر، والمقصود أنَّ الإنسان إذا رأى أنَّ الإمارة تحتاج إليه، وأن المسألة فيها خيانات، وفيها فساد، ورأى الإصلاح؛ فهو مأجورٌ.\nس: ألا يكون من تزكية النَّفس؟\nج: لا، ما قصد التَّزكية إذا رأى من نفسه أنه قادرٌ على الإصلاح.\nس: ما المقصود بـ \"المعصوم مَن عصم الله\"؟\nج: أي: سلَّمه الله، فالتَّسليم بيد الله، يعني: مَن وفَّقه الله وسلَّمه، فالأمر بيد الله جلَّ وعلا.","link":"https://binbaz.org.sa/fatwas/22414/ما-حكم-طلب-الكفء-الامارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الكُفْءُ إذا طلب الإمارة.mp3","categories":["أحكام الموظفين"]},{"id":2645,"question":"بالنسبة لموظف يأخذ إجازة اضطرارية ويذهب لأداء العمرة في رمضان؟","title":"حكم أخذ إجازة من العمل لأداء عمرة رمضان","answer":"الجواب: على حسب ما عندهم، إذا صار عندهم عند الحاجات الضرورية على حسب ما يفسّرونها هم إجازة ضرورية، العمرة ما هي بضرورية، لا بدّ يصرح لهم يقول بآخذ عمرة ويبيّن، أما إن كان مقصوده الحاجة فالعمرة حاجة، مصلحة.\nس: أكثر العمال يأخذون إجازة في رمضان وكأن رمضان مدعاة للكسل وكذا؟\nالشيخ: لا، ليتفرغوا للعبادة؛ الذي نيته صالحة الله يعينه.","link":"https://binbaz.org.sa/fatwas/22780/حكم-اخذ-اجازة-من-العمل-لاداء-عمرة-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أخذ إجازة من العمل ويذهب لأداء العمرة في رمضان.mp3","categories":["أحكام الموظفين"]},{"id":3069,"question":"بارك الله فيكم، اشتغل أحد الأفراد بالشركة وبعد التحقق بالشركة سمع أن مصدر فلوس هذه الشركة حرام، حيث كان صاحبها وزيرًا في إحدى الدول العربية ويقال إنه سرق أموال الدولة وبعد تركه الوظيفة فتح عدة شركات، ومن ضمنها هذه الشركة، وبعض الناس تقول ذلك، والبعض الآخر يقول إنه اتهام باطل ليس له أساس، وذلك ما هو إلا أن الشركة أصبحت من أحسن الشركات في السوق وهذا قول المنافسين حتى تخسر الشركة ويقل حجم التعامل معها، يسأل الموظف بالشركة: هل إذا كانت الأموال مسروقة فعلًا وهي في الأصل أموال الدولة، فهل فلوسها التي نتقاضاها من الشركة حرام؟","title":"حكم مَن يعمل في شركة مصدر أموالها حرام","answer":"الجواب: إذا علم ذلك لا يساعد، أما إذا لم يعلم فالإشاعات ما عليها عمل، أما إذا علم أن الشركة أموالها حرام لا يعمل فيها.\nالسؤال: طيب، هل عليه ترك العمل؟\nالشيخ: إذا علم، أما الإشاعات ما تنفع.\nالسؤال: ما تنفع الإشاعات؟\nالشيخ: لا لا.","link":"https://binbaz.org.sa/fatwas/23229/حكم-من-يعمل-في-شركة-مصدر-اموالها-حرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الواجب على من يعمل في شركة مصدر أموالها حرام.mp3","categories":["أحكام الموظفين"]},{"id":3757,"question":"إنسان موظف، عميل عنده...؟","title":"حكم الهدايا للعمال والموظفين","answer":"الجواب: كل الهدايا مثل ما سمعت، إلا إذا كان بينك وبينه معرفة سابقة وهدايا سابقة لقرابة أو مجاورة أو نحو ذلك، فالعادة السابقة لا تدخل في هذا.\nس: إذا جاءت عاملاً في العمل مكافأة؟\nالشيخ: إذا كان من ولي الأمر لا بأس، سمعت كلام النبي: أفلا قعد في بيت أبيه وأمه فيرى هل يهدى إليه؟ هو ما أهدى إليه إلا لأجل ولايته هذه.\nس: وإن كان لا تقتضي المصلحة إلا بذلك؟\nالشيخ: ولو زعم أن المصلحة تقتضي ذلك، لا يعطيه شيئًا، يصبر ويأخذه بالطرق المعروفة، الطرق الشرعية.\nس: حكمها من الغُل؟\nالشيخ: الغُل من الغلول، الغِل: الحقد، والغِل: القيد الذي يكون في العنق، والغلول ما يأخذه الإنسان من الغنيمة وغيرها بغير حق.","link":"https://binbaz.org.sa/fatwas/23949/حكم-الهدايا-للعمال-والموظفين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الهدايا للعمال.mp3","categories":["الهبة والعطية","أحكام الموظفين"]},{"id":5168,"question":"يقول: يتساهل كثيرٌ من الناس فيما يُسمَّى بالحق العامّ، فيستخدمون سيارات دائرات حكومية لأغراضٍ شخصيةٍ، أو الهاتف في العمل يتَّصلون منه على أقارب خارج المنطقة، أو غير ذلك، ما ضابط هذا؟ جزاكم الله خيرًا.","title":"ما حكم استعمال الحق العام لأغراضٍ شخصيةٍ؟","answer":"الجواب: الواجب على العامل والموظف أن يتَّقي الله، وأن لا يستعمل ما تحت يده إلا بما أباحته الدولة وأذنت فيه، فإذا كان الشيء الذي يفعله مباحًا له فلا بأس، وإلا فليحذر، وإذا شكَّ يتورّع ويترك ما شكَّ فيه: دع ما يريبك إلى ما لا يريبك هكذا قال ﷺ، وقال أيضًا: مَن اتَّقى الشُّبهات فقد استبرأ لدينه وعرضه، وما كان معروفًا أنهم أجازوه فلا حرج في ذلك، وما منعوه وجب تركه؛ لأنَّ على كل مسلمٍ السمع والطاعة في المعروف، فما مُنِعَ على الموظف لا يأتيه، وما أُذِنَ له يأتيه، وما اشتبه عليه يدعه: دع ما يريبك إلى ما لا يريبك.","link":"https://binbaz.org.sa/fatwas/30093/ما-حكم-استعمال-الحق-العام-لاغراض-شخصية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 117.mp3","categories":["أحكام الموظفين"]},{"id":5173,"question":"يقول  بعض الموظفين يستغلُّون سلطتهم الوظيفية باستخدام الأفراد العسكريين أو الموظفين في إداراتهم لقضاء شؤونهم الخاصَّة المنزلية، وإنهاء مُعاملتهم الخاصَّة لدى الدوائر الحكومية، فما رأي سماحتكم؟","title":"حكم من يستغل سلطة وظيفته لبعض شأنه الخاص","answer":"الجواب: لا يجوز استخدامهم في الحاجات الأخرى إلا بطريقةٍ خاصةٍ بينه وبين الخادم في غير وقت العمل، فإذا تراضى هو والخادم في أوقاتٍ أخرى أنه يخدمه ويُعطيه ما يُرضيه ويُعينه فهذا شيءٌ إليه، أما وقت العمل فيكون خاصًّا بمحل العمل الحكومي، فيكون الخادم وغير الخادم يعملون في محلِّ العمل الحكومي الذي هم مأمورون به، وإذا كانت له حاجات يكون له خادمٌ آخر غير الخادم الذي للحكومة -خادم لحاجات البيت والحاجات الأخرى- يكون له خادمٌ آخر تبع البيت، تبع حاجاته هو، تبع ماله، يخصّه. وأما خادم الحكومة فيكون في عمل الحكومة، وإذا كان هذا الخادم يعمل خارج العمل في وقت الإجازة ووقت الراحة بشيءٍ بينه وبين رئيسه، لا يستغله لأنه خادم، بل بينه وبينه مساعدة، فيُعطيه مساعدةً باختياره ورضاه، لا بالوعيد ولا بالتهديد؛ فلا يضرّ هذا، أما بالوعيد أو بالتَّهديد إنْ لم يفعل فهذا لا يجوز.","link":"https://binbaz.org.sa/fatwas/30102/حكم-من-يستغل-سلطة-وظيفته-لبعض-شانه-الخاص","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 128.mp3","categories":["أحكام الموظفين"]},{"id":6426,"question":"وآخر يسأل فيقول: أفيدكم أنني موظف والجهة التي أعمل بها توافق على انتداب أفراد لمدد مختلفة، دون أن يذهب الفرد المنتدب لأداء أي مهمة، والمسؤولون يعرفون ذلك، ويعتبرون بدل الانتداب هذا تشجيع للفرد، ومكافأة، وتشجيع له على ما يقوم به من عمل، و هل هذا المبلغ الذي آخذه عن بدل الانتداب حلال أم حرام؟","title":"حكم أخذ بدل انتداب دون الذهاب إلى ما انتدب إليه","answer":"الجواب: المعروف أن هذا لا يجوز، كونه يكتب له انتداباً، وهو ما انتدبه وهو في عمل ... ولا راح، المعروف أن هذا حيلة، وكذب، وغش للدولة، فيكون محرمًا؛ لأن هذا بغي بغير حق.  أما إذا كانت الدولة قد بلغها هذا، وأذنت للمسؤولين بأن يعملوا هذا لموظفيهم، وأن هذا عن شيء اتفقت عليه الدولة مع المديرين، أو مع الوزراء؛ فلا بأس بهذا؛ لأن الدولة ترى المصلحة، فإذا رأت أن تندب بعض الناس بالانتداب في الحقيقة، وأن يعطى المكافأة للمنتدب؛ تشجيعًا له على عمله كما يعطى المنتدب ما يعطى لأجل إعانته على عمله، ولا يجد في المقابلة تعباً، وفراقه لأهله، ونحو ذلك، إذا رأت الدولة ذلك لأجل تطييب نفوس المقيمين، ونشاطهم في العمل، وتشجيعهم في العمل هذا شيء إليها.  أما من جهة الموظف الذي فوقه يخدع الدولة، ويغش الدولة، ويعطيه شيئاً ما له حقيقة، فالأظهر من الأصول: أن هذا ربًا، ولا يجوز، محرم.","link":"https://binbaz.org.sa/fatwas/2143/حكم-اخذ-بدل-انتداب-دون-الذهاب-الى-ما-انتدب-اليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_792.mp3","categories":["الكسب المحرم","أحكام الموظفين"]},{"id":6518,"question":"نرجو منك أن توضح لي ولجميع الحاضرين حلية المال بالنسبة للعمل، فمن شروط استجابة الله دعاء العبد أن يكون مطمعه، وملبسه حلالًا، والمشاهد أن معظمنا من الموظفين في الدوائر الحكومية قد يحصل من الشخص أن يتأخر عن حضور بداية الدوام، أو الذهاب مثلًا الساعة الثانية في بعض المصالح الحكومية، والخروج من العمل أثناء الدوام لقضاء بعض الأعمال، بعد استئذان رئيس القسم، وليس الرئيس المباشر، أو بدون استئذان، قد يكون كسلاناً، وقد يكون ليس لديه الراحة الكاملة، حيث بعض الموظفين قد يغفو في المكتب بعض الأحيان، أي ينام، فما رأي فضيلتكم؟","title":"الواجب على الموظف تجاه وظيفته","answer":"الجواب: لا ريب أن الواجب على العامل أن يؤدي العمل بأمانة، العامل أخذ الأجرة في مقابل عمله، سواء كان موظفًا في دائرة حكومية، أو في غير ذلك، الواجب على العامل أن يجتهد في أداء العمل، وأن يحفظ الوقت الذي تمت الإجارة على العمل فيه، هذا هو الواجب عليه.  فإذا فرط في شيء من ذلك في أسباب اقتضت ذلك من عارض منعه من شيء من ذلك، أو نوم منعه من ذلك، ولم يتعمد ذلك، فنرجو أن يكون ذلك ... العفو، ولا يضره ذلك -إن شاء الله- ولا يضر مطمعه، ولكن لا ينبغي أن يتعمد التكاسل والتساهل بهذه الأمور إذا تأخر كثيرًا، أو يخرج قبل الوقت من غير مبالاة، هذا كله خطر عظيم في دينه من جهة الإثم، ومن جهة المصدر أيضًا، فإنه لم يؤد الحق الذي يستحل به المكسب، وهو الأجرة.  فالواجب تقوى الله في ذلك، وأن يحذر التساهل مهما أمكنه، وأن يتقي الله ما استطاع، وما فات من ذلك من الشيء اليسير ... بأعذار عارضة فنرجو أن يعفو الله عنه سبحانه.","link":"https://binbaz.org.sa/fatwas/2265/الواجب-على-الموظف-تجاه-وظيفته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_888.mp3","categories":["الإجارة","أحكام الموظفين"]},{"id":6581,"question":"ما حكم راتب الموظف الذي يتساهل في عمله، ولا يؤديه على الوجه الأكمل؟ هل هو يصبح حرامًا، أم حلالًا؟","title":"حكم راتب الموظف المتساهل في عمله","answer":"الجواب: راتبه فيه شبهة، ينبغي له أن يتقي الله، وأن يعتني بعمله حتى لا يكون في راتبه شبهة؛ لأن الواجب عليه أن يؤدي الحق الذي عليه؛ حتى يستحل الراتب، فإذا كان لا يبالي؛ فراتبه على كل حال بعضه حرام، فينبغي له أن يحذر، ويتقي الله جل وعلا.","link":"https://binbaz.org.sa/fatwas/2428/حكم-راتب-الموظف-المتساهل-في-عمله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_955.mp3","categories":["الإجارة","أحكام الموظفين"]},{"id":7005,"question":"أنا موظف في مؤسسة حكومية، والعمل يومي ومحدود بالعدد، وبعض الزملاء يقضون أوقاتهم بقراءة الصحف، وفي التحدث إلى بعضهم البعض؟الشيخ: أعد؟الطالب: أنا موظف في مؤسسة حكومية، والعمل يومي، ومحدود بالعدد، وبعض زملائي يقضون أوقاتهم، أو أكثر أوقاتهم بقراءة الصحف، والتحدث، سؤالي هو: هل أنا ملزم بالعمل حتى نهاية الدوام الرسمي، أو أني ملزم بالعمل بقدر نصيبي في العدد الممكن عمله لكل شخص، إذا كان عندنا خمسة، فهل علي أن أقوم بخمس العمل وكفى؟","title":"واجب الإنسان تجاه وظيفة عمله","answer":"الجواب:\n\nعليك أن تقوم بما تستطيع حسب الوظيفة التي وكلت إليك، عليك أن تقوم بما تستطيع فتجتهد، ولا تتأسى بأهل البطالة، لا تتأسى بهم، عليك ألا تتأسى بأهل البطالة، والذين يلعبون بالأوقات بالصحف وغيرها، وعليك أن تنصح، وتعمل ما تستطيع، إن استطعت أن تعمل كل ما عندك؛ فلا تبخل، وكن خيرًا منهم، مؤديًا للأمانة، ناصحًا للأمة، مستحلًا لما أعطوك من المال، لا تكسل، ولا تضعف، فعليك أن تؤدي العمل الذي نسب إليك، والذي لم ينسب إليك، لست المسؤول عنه، أنت مؤاخذ بما نسب إليك فقط.\n\nثم عليك أن تنصح زملاءك، تنصحهم، تقول لهم: اتقوا الله، ذروا عنكم الصحف، دعوا عنكم الأشياء التي ما لها كذا، عليكم أن تؤدوا الأمانة، عليكم أن تؤدوا العمل، تنصحهم في الله، المسلم أخو المسلم، ينصحه، ويعينه على الخير.","link":"https://binbaz.org.sa/fatwas/2935/واجب-الانسان-تجاه-وظيفة-عمله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1383.mp3","categories":["أحكام الموظفين"]},{"id":7015,"question":"أنا موظف في مؤسسة حكومية، والعمل يومي ومحدود بالعدد، وبعض الزملاء يقضون أوقاتهم بقراءة الصحف، وفي التحدث إلى بعضهم البعض؟الشيخ: أعد؟الطالب: أنا موظف في مؤسسة حكومية، والعمل يومي، ومحدود بالعدد، وبعض زملائي يقضون أوقاتهم، أو أكثر أوقاتهم بقراءة الصحف، والتحدث، سؤالي هو: هل أنا ملزم بالعمل حتى نهاية الدوام الرسمي، أو أني ملزم بالعمل بقدر نصيبي في العدد الممكن عمله لكل شخص، إذا كان عندنا خمسة، فهل علي أن أقوم بخمس العمل وكفى؟","title":"واجب الإنسان تجاه وظيفة عمله","answer":"الجواب:\n\nعليك أن تقوم بما تستطيع حسب الوظيفة التي وكلت إليك، عليك أن تقوم بما تستطيع فتجتهد، ولا تتأسى بأهل البطالة، لا تتأسى بهم، عليك ألا تتأسى بأهل البطالة، والذين يلعبون بالأوقات بالصحف وغيرها، وعليك أن تنصح، وتعمل ما تستطيع، إن استطعت أن تعمل كل ما عندك؛ فلا تبخل، وكن خيرًا منهم، مؤديًا للأمانة، ناصحًا للأمة، مستحلًا لما أعطوك من المال، لا تكسل، ولا تضعف، فعليك أن تؤدي العمل الذي نسب إليك، والذي لم ينسب إليك، لست المسؤول عنه، أنت مؤاخذ بما نسب إليك فقط.\n\nثم عليك أن تنصح زملاءك، تنصحهم، تقول لهم: اتقوا الله، ذروا عنكم الصحف، دعوا عنكم الأشياء التي ما لها كذا، عليكم أن تؤدوا الأمانة، عليكم أن تؤدوا العمل، تنصحهم في الله، المسلم أخو المسلم، ينصحه، ويعينه على الخير.","link":"https://binbaz.org.sa/fatwas/2935/واجب-الانسان-تجاه-وظيفة-عمله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1383.mp3","categories":["أحكام الموظفين"]},{"id":7113,"question":"أنا أعمل في المباحث العامة، وقد سمعت من بعض إخواني أن هذا العمل حرام؛ لأن فيه التجسس على المسلمين، وقد يدخل فيه الشرك؛ لأنه يدخل المسجد ليس لصلاة، ولكن من أجل مراقبة إمام المسجد، وأنا أرجو من سماحتكم الجواب الكافي، على حد تعبيره؟","title":"حكم العمل في المباحث العامة للدولة","answer":"الجواب:\n\nبسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله، وأصحابه، ومن اهتدى بهداه، أما بعد:\n\nفلا ريب أن المباحث فيها خطر عظيم على رجالها، ولكن من قصد منهم الخير والنفع للمسلمين، وحماية البلاد من شر الأشرار، والسعي فيما يتعلق بالإصلاح، والنفع العام؛ فهذا لا يضره ذلك، وعلى حسب نيته يؤجر في أعماله فيما يتعلق بالتجسس على من يخشى شره على المسلمين، وذلك معناه البحث عنهم، والتعرف عليهم، وليس من التجسس الذي حرمه الله، التعرف على أهل الشر لإبعادهم من البلاد، أو لمجازاتهم على ما يفعلون ممن أظهر الشر بين المسلمين.\n\nوهكذا التعرف على أئمة المساجد، هل قاموا بواجبهم؟ هل هم صالحون للإمامة، أم ليسوا صالحين للإمامة؟ كل هذه أعمال لها أهميتها، ولها فضلها، والواجب على المسؤولين عنها أن يعتنوا بها، وأن يراقبوا.\n\nوهكذا المؤذنون، وهكذا غيرهم كالفراشين، وهكذا الأمور الأخرى، فإذا كان المقصود من ذلك هو نفع المسلمين، والتعرف على من قام بالواجب؛ حتى يشكر ويقر، ومن كان عمله خلاف الحق، وكان يضر في أعماله حتى يمنع من ذلك في تأديبه على ما فعل، أو فصله من عمله، أو إبعاده من البلاد لأعماله السيئة، فهذا له أجره على ما فعل.\n\nأما التجسس لإيذاء المسلمين، وظلمهم، والعدوان عليهم؛ لأخذه المال، ولكونه يتقرب بذلك للمسؤولين، ولا يهمه إلا مصلحته الحاضرة العاجلة؛ فهذا عليه خطر عظيم، وبلاء كبير، ولا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/3142/حكم-العمل-في-المباحث-العامة-للدولة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1500.mp3","categories":["أحكام الموظفين"]},{"id":7688,"question":"هذه الرسالة من الجماهيرية العربية الليبية الشعبية الاشتراكية، يقول فيها مرسلها عبد العاطي علي قلاد ، وقد بعث بعدة أسئلة، يقول في السؤال الأول: هل يجوز للموظفين في المصالح العامة أن يأخذوا منها شيئاً كالقلم والورق مثلاً؟","title":"حكم استعمال متعلقات العمل للاستعمال الشخصي","answer":"الجواب: الذي يظهر أنه ليس لهم ذلك لأنفسهم، إلا إذا كانت الدولة تسمح بذلك، إذا كان عرف الدولة يسمح بذلك أن يأخذ من مكتبه لحاجته وبيته ما يريد، أما إذا كان لمصلحة المكتب ولمصلحة الحكومة هذا معروف لا بأس، أما كونه يأخذ أقلام أو قراطيس أو أشياء أخرى لحاجات أخرى لبيته يفرضها من المكتب لبيته، فالظاهر أنه لا يجوز ذلك إلا بعرف، إذا كان عرف في الدولة أنها تسمح بهذا الشيء، وأن هذا الشيء مسموح فيما بينهم فلا بأس، أما إذا كان ليس بعرف فإن الأصل أن ما في المكتب يبقى في المكتب، والذي في البيت يكون للبيت، الذي في بيته من ماله، والذي في المكتب يكون من المكتب. نعم.","link":"https://binbaz.org.sa/fatwas/4887/حكم-استعمال-متعلقات-العمل-للاستعمال-الشخصي ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_027/02704.mp3","categories":["الرقائق","أحكام الموظفين"]},{"id":8044,"question":"سؤاله الرابع يقول فيه: إذا قال الموظف لرؤسائه: عندي ظروف كذا وكذا، وأريد السماح لي عن العمل لمدة يوم أو يومين، وهو غير صادق إنما عنده ظروف أخرى بسيطة، أو يريد الراحة من العمل، ولو أعلمهم بالحقيقة لم يأذنوا له، فماذا عليه في ذلك؟","title":"حكم أخذ إجازة من العمل بأعذار كاذبة","answer":"الجواب: الواجب عليه الصدق، وأن لا يعتذر إلا بالحقيقة، فإن سمحوا له فالحمد لله، وإلا باشر عمله، أما الكذب فلا يجوز، بل هذا منكر وتملص من الواجب، فلا يجوز له ذلك لأمرين: أحدهما: أنه كذب، والأمر الثاني: أنه ترك لواجب بدون عذر فلا يجوز له ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/5844/حكم-اخذ-اجازة-من-العمل-باعذار-كاذبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_081/08110.mp3","categories":["الرقائق","أحكام الموظفين"]},{"id":8610,"question":"هذه رسالة وردتنا من السائل أحمد سالم العزب مشولي من أبناء باب المندب في الجمهورية العربية اليمنية، يقول في رسالته السؤال الأول: كنت مدرساً للطلاب لتحفيظ القرآن الكريم في إحدى القرى المجاورة براتب شهري، والراتب يدفع لي من قبل آباء الطلبة، وبعد فترة قصيرة تبين لي بأن هذا الراتب من مال حرام، ومع علمي بهذا استمريت في الدراسة لمدة ستة أشهر، أرجو إفادتي ما حكم هذا الراتب الذي تقاضيته في هذه المدة، وهل لي أجر في هذه الدراسة أم لا؟","title":"حكم أخذ الراتب المقدم إذا كان من مال حرام","answer":"الجواب: إذا علمت أنه من مال حرام فلا تأكله ولا تأخذه، والذي دخل عليك تصدق به على الفقراء أو يصرف في مشروع خيري، وإن أكلت السابق الذي لم تعلم به فأرجو ألا يكون عليك شيء لأنك لم تعلم، والله يقول سبحانه وتعالى في المرابي: فَمَنْ جَاءَهُ مَوْعِظَةٌ مِنْ رَبِّهِ فَانتَهَى فَلَهُ مَا سَلَفَ وَأَمْرُهُ إِلَى اللَّهِ [البقرة:275].\nفالذي دخل عليك قبل أن تعلم أرجو أن لا يكون عليك حرج منه؛ لأنك لم تعلم، وإن تصدقت بمقابله وسلمت منه فذلك أحوط لك، أما الذي علمته أنه حرام ثم أخذته فليس لك، بل يجب عليك أن تخرجه من مالك وتصرفه في بعض وجوه الخير مثل الصدقة على بعض الفقراء، ولا تعلمهم بشأنه، مثل: صرفه في تعمير بعض دورات المياه، مثل قضاء دين عن معسر عليه دين أو ما أشبه ذلك، ولا تأكله أنت لأنك علمت أنه حرام، فليس لك أن تأكله نعم، وأما أنت فأنت مأجور إن شاء الله على تعليم القرآن، ولك أن تأخذ الأجرة على تعليم القرآن من بيت المال أو من الأهالي، وأنت على خير إن شاء الله، يقول النبي ﷺ: خيركم من تعلم القرآن وعلمه ويقول: إن أحق ما أخذتم عليه أجراً كتاب الله فالمعلم يباح له أخذ الأجرة على الصحيح، ولا حرج عليه وهو مأجور. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6745/حكم-اخذ-الراتب-المقدم-اذا-كان-من-مال-حرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_210/21011.mp3","categories":["الرقائق","أحكام الموظفين"]},{"id":9513,"question":"له سؤال أيضاً يقول فيه: أعمل مدرساً، والمدرس عندنا ليست له إجازة أثناء فترة الدراسة، وعندي عمل في منزلي يحتم علي حضوري والانقطاع عن المدرسة، فقدمت إجازة مرضية وذهبت لطبيب وأخذ مني جنيهين وأعطاني الإجازة، ولولا ذلك لم تحصل لي، فهل يصح عملي هذا أم يلزمني إعادة مرتب هذه الأيام؟","title":"حكم أخذ إجازة مرضية كذباً","answer":"الجواب: هذا كذب ولا يجوز، حرام عليك وعلى الطبيب الذي أعطاك الشهادة، وهو منكر وتعاون على الإثم والعدوان، فعليك أن تستسمحهم وتخبرهم بالحقيقة أو ترد عليهم ما يقابل هذا الجزء الذي كذبت فيه إلا أن يسمحوا عنك؛ لأن الرسول ﷺ نهى.. بل الله جل وعلا نهى عن الكذب، والرسول حرم الكذب، وأخبر عليه الصلاة والسلام أنه من سمات أهل النفاق، من آيات المنافقين: إذا حدث كذب، وإذا وعد أخلف، وإذا اؤتمن خان نسأل الله العافية. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7671/حكم-اخذ-اجازة-مرضية-كذبا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_243/24305.mp3","categories":["أحكام الموظفين"]},{"id":9621,"question":"وهذه رسالة من إبراهيم محمود التائب من السودان، يقول: أنا أعمل حداداً في مصلحة حكومية، وأحياناً يطلب مني بعض الإخوة الذين يعملون معنا أن أعمل له كرسياً أو سريراً، ويأخذ موافقةً من المسئول على ذلك، لكن يعطيني مبلغاً من المال إذا أنا أصلحته له، فهل يجوز لي ذلك؟","title":"حكم الأعمال الخاصة في أماكن الدولة وأخذ أجرة لذلك","answer":"الجواب: إذا كان في مصلحة حكومية فليس لك ذلك لا أنت ولا المسئول، أما إذا كان في وقت آخر بعد انتهاء الدوام ..... في بيته وأصلحت له في بيته شيئاً فلا بأس أن تعامله بالأجرة يعطيك ما تيسر.\nأما أن تتفق معاً على أخذ الكرسي أو السرير في محل الحكومة ومن مال الحكومة هذا لا يجوز، وهذا من الخيانة، إلا إذا كانت الدولة قد سمحت بهذا للمسئول، فينبغي لك التورع عن هذا والحذر؛ لأن المسئولين قد يتساهلون بهذا، بعض المسئولين قد يتساهلون، فالذي نوصيك به الحذر. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7786/حكم-الاعمال-الخاصة-في-اماكن-الدولة-واخذ-اجرة-لذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_249/24912.mp3","categories":["أحكام الموظفين"]},{"id":9699,"question":"تقول هذه الأخت السائلة من اليمن أيضاً: لي ابن موظف عند صاحب مال، وليس له راتب شهري معين؛ لأنه كلما احتاج شيء من المال أعطاه إياه، ولو قدرنا الذي عند التاجر لوجدناه حوالي مائة ألف ريال، لكنها عند صاحب المال يعتبرها جزء من ماله يتاجر بها، يعني: لا يعطي لابنها مالاً إنما ما له من حق يجعله ضمن ماله أي التاجر، وعند إخراج الزكاة قال ابني للتاجر: كم لي عندك حتى أدفع زكاة مالي، قال التاجر: أنا الذي سأزكي مالك مع مالي؟","title":"حكم التوظف دون تحديد الراتب","answer":"الجواب: هذا العامل يجب أن يعين له راتب معين، وليس له أن يعمل هكذا من دون راتب معين؛ لأن هذا يفضي إلى النزاع والخصومة، ولأنه راتب مجهول وأجر مجهول فلا يجوز، فالواجب أنه يعين له راتب معين يصطلحان عليه، وبعد ذلك هو الذي يزكيه كلما حال عليه الحول زكاه صاحبه العامل، وإذا اصطلحا عما مضى بشيء معلوم فإنه يزكيه العامل بعد أن يحول عليه الحول. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7894/حكم-التوظف-دون-تحديد-الراتب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_254/25403.mp3","categories":["الإجارة","أحكام الموظفين"]},{"id":9701,"question":"أخيراً يسأل الأخ سليمان من المدينة المنورة ويقول: هناك قضية وهي أننا نأتي ونوقع لحضور الدوام في الدائرة، ونقضي بعض الوقت بها وبعض الوقت الآخر نقضيه في شئوننا الخاصة، وترتيب أعمالنا، والمدير وغالب موظفي الدائرة أكثر الأحيان مسافرين، فهل الراتب حلال أم حرام، أفيدونا أفادكم الله؟","title":"حكم قضاء بعض وقت الدوام في الشئون الخاصة","answer":"الجواب: الواجب على المؤمن أن يؤدي الأمانة، فالوظائف أمانة، ولها مدة معلومة ووقت معلوم، فالواجب أن تؤدى في وقتها، وأن يحافظ على الوقت، ويؤدي العمل حتى ولو كان ما عنده عمل ينتظر، يبقى في العمل حتى ينتظر حتى يحال إليه عمل، أو يراجعه مراجع، فليس له أن يفرط في ذلك إلا بإذن من مرجعه، أو بشيء جرت به العادة يعفى عنه معروف، ليس فيه نزاع بين الجميع وليس يختفى به، بل أمر معلوم، هذا مستثنى إذا وجد شيء قد وافقت عليه الدولة وسمحت به لشيء خاص قد عرفت أسبابه، وإلا فالأصل هو وجوب المحافظة على الدوام، وأن تؤدي هذه الأمانة بكل عناية، من أولها إلى آخرها، وليس لك أن تفرط في ذلك، فإنك مستأجر ولك أجرة، فعليك بأسباب حلها واحذر أسباب تحريمها، والله المستعان. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7856/حكم-قضاء-بعض-وقت-الدوام-في-الشىون-الخاصة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_252/25213.mp3","categories":["أحكام الموظفين"]},{"id":11294,"question":"القضية الثالثة التي يسأل عنها أبو عزام هي أنه عمل براتب عند والده، وعلم أن والده لن يعطيه ذلك الراتب، فتقاضاه بدون علم والده، من مردود المحل الذي يعمل فيه، فهل ما فعله صحيح؟ جزاكم الله خيرًا.","title":"حكم من عمل لدى والده براتب وأخذ راتبه دون علمه","answer":"الجواب:  إذا كان قام بالعمل الواجب الذي أمره به والده ورتب عليه الراتب فلا بأس، إذا قام بالعمل على الوجه المطلوب فإنه يأخذ الراتب الذي جعل له إذا كان بقدر العمل، لو كان يعمل أجنبي لكان بهذا الراتب، يعني: ما يكون حيفًا على إخوانه، يكون أعطاه بقدر عمله. نعم. المقدم: جزاكم الله خيرًا. وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9471/حكم-من-عمل-لدى-والده-براتب-واخذ-راتبه-دون-علمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_376/37603.mp3","categories":["أحكام الموظفين"]},{"id":11318,"question":"موظف يخرج بإذن موقع من رئيسه المباشر ومن مدير الإدارة لمدة ساعة أو ساعتين أو ثلاث أو اليوم كله مثلًا، فهل عليه شيء، وما حكم الراتب الذي يستلمه كاملًا في كل شهر؟الشيخ: أعد.المقدم: موظف يخرج بإذن موقع من رئيسه المباشر ومن مدير الإدارة لمدة ساعة أو ساعتين أو ثلاث أو اليوم كله، فهل عليه شيء، وما حكم الراتب الذي يستلمه كاملًا آخر الشهر؟","title":"حكم من يستأذن من مسئوله ساعات عن العمل ولا تخصم","answer":"الشيخ:  نرجو ألا يكون عليه شيء إذا كان بإذن المسؤول نرجو ألا يكون عليه شيء، إلا إذا كان عن خيانة وعن قلة مبالاة فلا يجوز، إذا عطل العمل أو سامحه لأجل مصلحة خاصة لمديره أو ما أشبه ذلك، أما لعارض يعرض له وسامحه مديره أو رئيسه لعارض يعرض له فنرجو ألا حرج عليه، أما إذا كان على سبيل الخيانة والتساهل أو مصالح الرئيس أو المدير هذا لا يجوز.","link":"https://binbaz.org.sa/fatwas/9506/حكم-من-يستاذن-من-مسىوله-ساعات-عن-العمل-ولا-تخصم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_377/37717.mp3","categories":["أحكام الموظفين"]},{"id":12235,"question":"يقول في آخر سؤال له: لي أخ يعمل في مجال الدعاية لشركة أدوية، ويتسلم بعض الأدوية لتوزيعها كعينات، فهل يحل له إعطاء ذويه منها، أم يحرم ذلك؟","title":"حكم تصرف موزع الشركة في العينات التي يوزعها للعملاء","answer":"الجواب: ليس له أن يعطي ذويه إلا بإذن من الشركة، إذا سمحت أن يعطي أحدًا يعطي، فليس له أن يعطي أحدًا لا قراباته، ولا غيرهم إلا بإذن الشركة، إذا كان إنما مهمته يري الزبون، يطلعهم عليه حتى يعرفوا الدواء، لكن ليس له أن يعطي أحدًا من الناس إلا بإذن الشركة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10423/حكم-تصرف-موزع-الشركة-في-العينات-التي-يوزعها-للعملاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_447/44711.mp3","categories":["الكسب المحرم","أحكام الموظفين"]},{"id":12925,"question":"رسالة مطولة وصلت إلى البرنامج من أحد الإخوة المستمعين رمز إلى اسمه بالحروف (د. ع. م) من الرياض، الرسالة برمتها تكشف عن شخصية صاحبها فيقول: بسم الله الرحمن الرحيم، سماحة والدنا البار الشيخ: عبدالعزيز بن عبدالله بن باز -حفظه الله ورعاه آمين- أحييك بتحية الإسلام الخالدة، تحية أهل الجنة، السلام عليكم ورحمة الله وبركاته، وبعد: والدي العزيز أطال الله في عمرك، وجعلك ذخرًا للإسلام والمسلمين، إني أحبك في الله وأسأل الله أن يحشرني وإياك وجميع المسلمين مع الذين أنعم الله عليهم من النبيين والصديقين والشهداء والصالحينن وحسن أولئك رفيقًا، وبعد: عندي سؤال هو: أنا شاب -ولله الحمد والمنة- ملتزم بجميع تعاليم الإسلام، وأسأل الله لي ولك الثبات على الحق إلى يوم المعاد، وقد توظفت في إحدى الوزارات، وأنا أريد أن يكون الراتب الذي أتقاضاه حلالًا، ولا يكون فيه قرش واحد حرام؛ لأنني أريد أن أكون مستجاب الدعوة، كما قال  لـسعد بن أبي وقاص: أطب مطعمك؛ تكن مستجاب الدعوة ولا أريد أن أكون مثل الأشعث الأغبر الذي يمد يديه إلى السماء وملبسه حرام ومطعمه حرام ومشربه حرام وغذي بالحرام فأنى يستجاب له، وأنا آتي للدوام في الصباح الساعة السابعة والنصف أكون جالسًا على مكتبي، ولا أستخدم الأقلام والأوراق والدبابيس وكل أغراض العمل إلا في العمل، ولا أستعملها لحاجاتي الخاصة، بل أستخدمها لحاجة العمل، ولكن هناك ثلاثة أشياء أريد أن أسأل عنها -بارك الله فيك- وهي: جميع موظفي الإدارة التي أعمل فيها يخرجون في الساعة الثانية ظهرًا، وفي الثانية والربع لا تجد في الوزارة أحدًا إلا نادرًا، يخرجون جميعًا بما في ذلك مدير إدارتنا، وكذلك مدير القسم، وقد جلست أكثر من يوم أجلس إلى الثانية والنصف، وأخرج أنا لوحدي من الوزارة، وليس هناك أحد، فهل يجوز لي يا سماحة الشيخ أن أخرج معهم، أم لا؟ثانياً: التليفون في المكتب بعض الأيام يكون لي أشغال وحاجات تخصني، ولا تخص العمل بشيء، وأريد أن أتكلم في التليفون، فهل يجوز لي استعمال التليفون بغير حاجة العمل؟ثالثًا: بعض الأيام يكون لي أعمال وأشغال وحاجيات لا يمكن فعلها إلا في وقت الدوام، سواء داخل الوزارة، أو خارجها، فآخذ الإذن من رئيس القسم وأخرج، وبمجرد الانتهاء من العمل أرجع مباشرة إلى المكتب، فهل هذا جائز؟ رابعًا: بعض الأيام يكون عندي يوم كامل فيه شغل، أو أسافر إلى المدينة التي يسكن فيها والداي وزوجتي وأهلي، فأستأذن من رئيس القسم، ويأذن لي، وأتغيب ذلك اليوم، أو في منتصف الوقت يأذن لي، فهل هذا جائز؟ علمًا يا شيخي أن رئيسي هذا صاحب صلاحية في عملية دخولي وخروجي، وكشف الخروج والدخول يتم عن طريقه وبإذنه، أرجو يا سماحة الشيخ أن تجيب عن هذه الأسئلة بأسرع وقت ممكن حتى تنقذني من دوامة الأفكار التي تطاردني، فأنا لا أريد أن آكل حرامًا، بارك الله فيك، ونفع بك، وجعلك ذخرًا لأمة محمد ﷺ؟","title":"حكم استعمال أدوات العمل في الحاجات الشخصية والخروج أثناء الدوام","answer":"الجواب:  أولًا: نسأل الله لنا ولك الثبات على الحق، ونسأل الله أن يتقبل دعواتك، وأحبك الله الذي أحببتنا له. \nثانيًا: لا حرج فيما ذكرت من الأمور الأربعة، أولًا استعمال التلفون عند الحاجة لا بأس إذا لم يكثر إذا دعت الحاجة في شيء قليل، نرجو ألا حرج في ذلك -إن شاء الله- والدولة -بحمد الله- خيرها كثير، ونفعها عام، فالشيء اليسير يغتفر في مثل هذا؛ لأن الحاجة قد تدعو إلى هذا في بعض الأحيان، وكذلك خروجك في الساعة الثانية والربع مع الناس، لا بأس تخرج في الساعة الثانية والربع، وإذا جلسوا إلى النصف اجلس معهم، وإذا خرجوا اخرج معهم، لكن بعد الساعة الثنتين والربع، النهاية ثنتين وربع والربع الأخير هذا للخروج، والذهاب إلى البيت، ولا بأس أن تخرج مع الناس الساعة الثانية والربع لا قبلها. الثالثة: تخرج من المكتب بإذن المسؤول لبعض الحاجات التي تعرض، أو لأهلك في زيارة خاصة في بعض الأيام، بإذن صاحبك، بإذن المسؤول؛ لا حرج في ذلك -إن شاء الله- مع مراعاة القلة من هذه الأشياء، والحرص على أن تكون هذه الحاجات في غير الدوام، فإذا عرض في الدوام، ولم يتيسر قضاؤها إلا في الدوام؛ فلا حرج في ذلك -إن شاء الله- نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11141/حكم-استعمال-ادوات-العمل-في-الحاجات-الشخصية-والخروج-اثناء-الدوام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_469/46910.mp3","categories":["أحكام الموظفين"]},{"id":13156,"question":"السائل الذي لم يذكر الاسم هنا يقول: بأنه شاب يعمل بمهنة محاسب يقول: كنت آخذ راتبًا، والحمد لله، ولكنه كان لا يكفيني، ومضيت ما يقارب من عامين، وخلال العامين أخذت مبلغًا على فترات بما يعادل ألفًا وسبعمائة ريال تقريبًا، وأخذت ذلك بدون علم صاحب المحل، كتزويد المبلغ في الفواتير، وأنا اعتبرت هذا المال سرقة، والآن أريد أن أخلص نفسي أمام الله -عز وجل- من هذا المال الحرام، ولكن أنا في حيرة، وإذا قلت لصاحب الشركة؛ رفضني من الشركة، وإذا علم الناس وزملائي؛ أخاف من موقفي أمامهم، علمًا بأنني في نظرهم ملتزم بشرع الله، وجهوني في ذلك، ونيتي -يا سماحة الشيخ يعلم الله- التسديد، ولكن ظروفي الآن لا تسمح، فماذا أعمل؟","title":"حكم من اختلس مالاً من محل عمله وكيفية إرجاعه","answer":"الجواب:  الواجب عليك رد المال إلى صاحبه بالطريقة التي تمكنك مهما أمكن، ولو بغير اسمك، باسم آخر، يقول للمسؤول عن الشركة: إن هذا مال عنده للشركة تذكره عنده، ويعطيه المسؤول عن الشركة بأي طريقة من دون اسمك أنت، باسم آخر، يقول: إن هذا أعطانيه شخص يقول: إنه للشركة، وإنه يريد براءة ذمته، إن هذا دخل عليه الشركة، ويريد براءة ذمته؛ فتبرأ ذمتك بذلك، فإن تعسر هذا، ولم يتيسر؛ فتصدق به عن أهله، تصدق به بنيته عن أهله في بعض الفقراء، والمساكين، مع التوبة، والندم، والإقلاع، وعدم العودة، العزم الصادق على ألا تعود في مثل هذا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11411/حكم-من-اختلس-مالا-من-محل-عمله-وكيفية-ارجاعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_510/51016.mp3","categories":["أحكام الموظفين"]},{"id":13419,"question":"قبول الصيدلي هدايا من الشركات المنتجة لبعض الأدوية، رغم أنه ليس صاحب المال الذي يعمل به، وإنما يعمل بالأجر فيه، وأن هذه الهدايا لن تؤثر على عملية البيع والشراء لمنتجات هذه الشركات التي قدمت الهدايا في الصيدلية التي يعمل بها هذا الصيدلي، وماذا لو أثرت هذه الهدايا على عملية البيع والشراء لمنتجات هذه الشركات في هذه الصيدلية؟","title":"حكم قبول العامل هدية من عملائه","answer":"الجواب: هذا أيضًا فيه تفصيل: إذا كانت الهدايا تسبب له خيانة في العمل، وإيثارًا هذه الشركة على غيرها، فيجتهد في بيع منتجاتها، وما يكون لها عنده، ويتساهل مع الباقين، فليس له ذلك، هو مؤتمن على بيع الجميع الذي عنده، وهو عامل، مأمور بأن يبيع ما عنده من هذه الأدوية، أو هذه السلع. فإذا كانت الهدية لا تعلق لها بذلك، بل أهدوا إليه؛ لأنه قريبهم، أو يعينهم على أشياء، أو لأنه وكيلهم، وهي لا تؤثر عليه في أعماله، ما نعلم ما يمنع من قبولها، أما إن كانت تؤثر في العمل، وتجعله يميز هذه الشركة، فيحرص على بيع منتوجها، وما توكله عليه، ويتساهل في أمر الباقين.. فهذا لا يجوز؛ لأن فيه خيانة. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11716/حكم-قبول-العامل-هدية-من-عملاىه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_477/47710.mp3","categories":["الهبة والعطية","أحكام الموظفين"]},{"id":13510,"question":"في آخر أسئلته يقول هذا السائل: رجل موظف، ولكن عند انتهاء ما عنده من معاملات يغادر الدوام قبل انتهائه، وخاصة في رمضان، وبعض الأحيان في غير رمضان نذهب في عمل ميداني، فنعود قبل الظهر، ونغادر إلى منازلنا، فهل هذا جائز؟","title":"حكم الخروج من العمل قبل انتهاء الدوام","answer":"الجواب: لا يجوز، بل يبقى في عمله حتى ينتهي الدوام إلا بإذن من مرجعه الذي هو المرجع، قد تأتيهم معاملة جديدة .. قد يحتاج إليه، فالواجب أن كل موظف يبقى في عمله حتى ينتهي الدوام إلا بإذن من الدولة، أو من المرجع الذي هو المسؤول عنه. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11824/حكم-الخروج-من-العمل-قبل-انتهاء-الدوام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_531/53108.mp3","categories":["أحكام الموظفين"]},{"id":13651,"question":"هذا السائل الذي رمز لاسمه بـ (م. ع. ت) يقول: من أخذ مكافأة لقاء عمله في المدارس الليلية، لكنه لم يقم بالواجب كاملًا، فتصدق بأكثر المال، هل عمله صحيح؟","title":"حكم من أخذ مكافأة وهو لا يستحقها","answer":"الجواب: عليه التوبة والصدقة؛ لأنه قصر في الواجب، فيتصدق بما يظن أنه يقابل ما ضيع، ومع التوبة إلى الله، وإن رد ذلك إلى صاحب المال؛ فهو الواجب أن يرد ما زاد على عمله إلى من أعطاه المال، ويستسمح، ويقول: إني قصرت وهذا.. إلا إن سمح له صاحب المال الذي أنفق المال سمح له قال: ولو، أنا سامح به لك؛ فلا بأس، أما إذا كان لا يسمح، أو هذا المال من بيت المال فلا يجوز، صاحب الحق يرده إليه، وإن كان من بيت المال يتصدق به على الفقراء، ولا يأخذ إلا ما يقابل عمله. نعم. المقدم: شكر الله لكم سماحة الشيخ، وبارك الله فيكم، وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/11988/حكم-من-اخذ-مكافاة-وهو-لا-يستحقها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_528/52822.mp3","categories":["أحكام الموظفين"]},{"id":13656,"question":"هذا السائل الذي رمز لاسمه بـ (م. ع. ت) يقول: من أخذ مكافأة لقاء عمله في المدارس الليلية، لكنه لم يقم بالواجب كاملًا، فتصدق بأكثر المال، هل عمله صحيح؟","title":"حكم من أخذ مكافأة وهو لا يستحقها","answer":"الجواب: عليه التوبة والصدقة؛ لأنه قصر في الواجب، فيتصدق بما يظن أنه يقابل ما ضيع، ومع التوبة إلى الله، وإن رد ذلك إلى صاحب المال؛ فهو الواجب أن يرد ما زاد على عمله إلى من أعطاه المال، ويستسمح، ويقول: إني قصرت وهذا.. إلا إن سمح له صاحب المال الذي أنفق المال سمح له قال: ولو، أنا سامح به لك؛ فلا بأس، أما إذا كان لا يسمح، أو هذا المال من بيت المال فلا يجوز، صاحب الحق يرده إليه، وإن كان من بيت المال يتصدق به على الفقراء، ولا يأخذ إلا ما يقابل عمله. نعم. المقدم: شكر الله لكم سماحة الشيخ، وبارك الله فيكم، وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/11988/حكم-من-اخذ-مكافاة-وهو-لا-يستحقها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_528/52822.mp3","categories":["أحكام الموظفين"]},{"id":13748,"question":"تقول هذه السائلة: تتغيب بعض المدرسات من التدريس في المدرسة، سواء كانت ابتدائية، أو متوسطة، أو ثانوية لعارض مرض، أو غيره، وتستلم راتبها كاملًا، هل في ذلك بأس؟","title":"حكم تغيب الموظف واستلامه الراتب كاملاً","answer":"الجواب: إذا أخبرت الجهات المسؤولة، وعلموا، وسامحوها؛ فلا بأس إذا علموا، عليها أن تخبر الجهة المسؤولة؛ حتى يعينوا من يقوم مقامها في العمل، وإذا سامحوها فالحمد لله، هذا شيء يخضع للتعليمات المتبعة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12110/حكم-تغيب-الموظف-واستلامه-الراتب-كاملا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_545/54521.mp3","categories":["أحكام الموظفين"]},{"id":13870,"question":"هذا السائل الذي رمز لاسمه بـ (م. ن) يقول: سماحة الشيخ! ما حكم استخدام سيارة العمل في الأشياء الخاصة؟ علمًا بأن المدير المباشر في المصلحة لا مانع لديه من ذلك، وجهونا في ذلك.","title":"حكم استخدام سيارة العمل في الأشياء الخاصة","answer":"الجواب: سيارات العمل تستخدم فيما تقتضيه التعليمات، وليس له أن يستعملها في غير ذلك، يكون خيانة، فإذا كانت التعليمات تبيح له أن يستعملها في كذا أو كذا فلا بأس، أما أنه يستعملها؛ لأن المدير تساهل معه أو نائب المدير، لا، الواجب أن يستعملها حسب التعليمات المتبعة التي قررتها الدولة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12255/حكم-استخدام-سيارة-العمل-في-الاشياء-الخاصة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_538/53802.mp3","categories":["أحكام الموظفين"]},{"id":14362,"question":"المستمع أحمد صالح زيد، بعث يسأل ويقول: رجل يعمل في محل تجاري براتب معين، ويأكل ويشرب ويلبس من داخل هذا المحل الذي يعمل فيه، ولكن بدون إسراف ولا تبذير، بل بالمعروف حسب حاجته، وأحيانًا يحتاج إلى شيء من خارج المحل، وقد يأخذ قيمة هذا الشيء من ذلك المحل، قد يزيد المبلغ وينقص عن عشرة أو عشرين ريال، هذا المهم أرجو الرد عليه، جزاكم الله خيرًا.","title":"حكم أخذ العامل من مال من يعمل معه","answer":"الجواب: ليس له إلا راتبه إلا أن يسمح له صاحب المحل، أما أن يأخذ من المحل حاجاته فلا إلا بإذن، إذا كان بينه وبينه مشارطة، وسمح له بذلك فلا بأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12842/حكم-اخذ-العامل-من-مال-من-يعمل-معه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_487/48709.mp3","categories":["أحكام الموظفين"]},{"id":14879,"question":"نعود مع مطلع هذه الحلقة إلى رسالة المستمع هشام عثمان عبدالله من السودان، عرضنا سؤالًا له في حلقة مضت، وفي هذه الحلقة يسأل ويقول: أنا رب عمل لثلاثة عمال في مجال البناء، وأعطي العامل الواحد راتب يومي معين. علمًا بأن راتبي اليومي هو عشرة أضعاف راتب العامل الواحد، هل هذا ما أتحصل عليه من عرق العمال حلال علي أم حرام؟أفيدوني، جزاكم الله خيرًا.","title":"حكم أخذ المشرف على عمل أضعاف ما يأخذه العمال","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: إذا كنت اتفقت مع رب العمل على أنه يعطيك أضعاف ما يعطى العامل، فالأمر إليه، ولا حرج عليك في ذلك.  أما إذا كنت أنت الذي فرضت لنفسك هذا الشيء، فالواجب عليك أن تخبر صاحب العمل، فإن أجاز لك ما رأيت وإلا فلا يجوز لك أن تأخذ شيئًا لا يعلمه، فعليك أن تخبر صاحب العمل حتى يعين لك راتبًا عن عملك، ويأمرك بالأجور التي تفعلها مع العمال. والخلاصة: أن عليك أن ترجع إلى صاحب العمل فهو الذي يعين لك الراتب أو يجعل لك الإذن في تعيين الراتب للعمال، وهو الذي يعين راتبك أنت سواءً مثل العامل أو أكثر أو أقل، وليس لك أن تجعل لنفسك راتبًا بدون إذن صاحب العمل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13358/حكم-اخذ-المشرف-على-عمل-اضعاف-ما-ياخذه-العمال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_645/nour_64501.mp3","categories":["أحكام الموظفين"]},{"id":15031,"question":"سؤال علي سالم من جدة الأخير، يقول: لقد تفضل الملك حفظه الله بمكرمة زيادة راتب على راتب شهر رمضان، ولكن الأوقاف كانت تسأل أئمة المساجد: هل أنت موظف أم لا؟ فمن كان موظفًا، لا تصرف له المكرمة؛ بحجة تكرار المكرمة، مع أن الأعمال مختلفة، فإذا قال لهم فراش: لست موظفًا، وهو يشتغل في العسس أو خلافه، فما حكم ما أخذه؟ هل يرجعه أم لا؟","title":"ما حكم أخذ الموظف أكثر من إكرامية بذرائع مختلفة؟","answer":"الجواب: هذا إلى الجهة المسؤولة، كل موظف يرجع إلى الجهة المسؤولة، نعم.","link":"https://binbaz.org.sa/fatwas/13532/ما-حكم-اخذ-الموظف-اكثر-من-اكرامية-بذراىع-مختلفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_653/nour_65306.mp3","categories":["أحكام الموظفين"]},{"id":15569,"question":"هذا السائل (م. ع. أ) يقول يا سماحة الشيخ: بأنه شاب كان يعمل بشركة من الشركات، ولكن يقول: فوجئت من أن الشركة قد خصمت علي أشياء بدون وجه حق، هذا من ناحية، ومن الناحية الأخرى قدمت أعمالًا أستحق عليها المكافأة، ولم يعطوني إياها، فاضطررت إلى أن أعمل ما يلي:عندما كنت أشتري أشياء للشركة كنت أحصل على خصم كبير من أصحاب المحلات، ولكن هذا بيني وبين أصحاب المحلات، وكنت آخذ الخصم في جيبي مثلًا الفاتورة بمائة جنيه أخذ خمسة وعشرين جنيهًا، والفاتورة تكتب بمائة، مع العلم أن الأسعار بالفاتورة مثل المحلات الخارجية، أي: أن قيمة الفاتورة لا تزيد عن الطبيعي، ولكن الذي يحدث هو زيادة الخصم لكثرة الشراء، ولا يكتب الخصم بالفاتورة.","title":"خصمت عليه الشركة فأخذ ما تعطى من خصم من المحلات","answer":"الجواب: الواجب عليك أن تحاسبهم، وأن تخاصمهم، حتى يكون الأمر بينًا، أما الخصم هذا فقد يزيد، وقد ينقص، وقد تكون متساهلًا فيما تدعي أنه حق لك، فالواجب عليك أن تكون المسألة بينك وبينهم من جهة الصلح، بينك وبينهم بواسطة من يتيسر من المصلحين، أو بواسطة المحكمة، وأن لا تفعل ما ذكرت؛ لأنك قد تزيد على ما أخذ منك، وقد تتساهل في الأمور، وقد تظن أنك مظلوم وأنت غير مظلوم، فالواجب أنك تحاسبهم بالمناقشة بينك وبينهم، أو بواسطة المصلحين والأخيار، أو بواسطة المحكمة إن دعت الحاجة للخصومة، هذا هو الواجب عليك حتى لا تأخذ إلا حقك. المقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14108/خصمت-عليه-الشركة-فاخذ-ما-تعطى-من-خصم-من-المحلات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_570/57007.mp3","categories":["الإجارة","أحكام الموظفين"]},{"id":16224,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين وضمنها عددًا من الأسئلة يسأل في أحدها ويقول: إذا تعاقد الرجل مع شركة، ثم إن هذه الشركة اشترطت عليه ألا يعمل في جهة أخرى، فأدى عمل هذه الشركة، ثم عمل، هل يكون ما كسبه من المال محرم؟ أم يكون حلالًا؟","title":"حكم الكسب الناتج عن مخالفة شرط التفرغ للشركة","answer":"الجواب: يقول النبي ﷺ: المسلمون على شروطهم فإذا تعاقدت معه على أنه يعمل معها كذا وكذا ساعة، ولا يعمل مع غيرها، والتزم بذلك، فالظاهر أنه يلزمه ذلك؛ لأن عمله مع غيرها قد يضر عملها، قد يتعبه، قد يأتي وهو تعبان، ما ينصح في العمل. فالحاصل أنه إذا كان التزم بالشرط؛ ليس له ذلك، والأموال التي أخذها بهذا الطريق لا تحل؛ لأنه أخذها بغير حق، والرسول ﷺ قال: المسلمون على شروطهم نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14899/حكم-الكسب-الناتج-عن-مخالفة-شرط-التفرغ-للشركة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_751/nour_75113.mp3","categories":["أحكام الموظفين"]},{"id":16558,"question":"المستمع (ع. ع) بعث برسالة مطولة بعض الشيء، ملخص ما في سؤاله الأول: أنه عمل لفترة طويلة خارج وقت الدوام، وكان يستلم الاستحقاق في ذلك، إلا أنه لم يكن يداوم بالفعل، والآن بدأ يفكر في هذا الموضوع، وضميره يؤنبه من ذلك، ويرجو التوجيه؟الشيخ: أعد.المقدم: يقول: إنه عمل فترة طويلة عملًا خارج وقت الدوام، واستلم المبالغ التي يحق له استلامها عن ذلك، وهو لم يداوم بالفعل، والآن أصبح يفكر في هذا الموضوع، وضميره يؤنبه لذلك، ويرجو من سماحتكم التوجيه، كيف يتصرف في تلك المبالغ؟","title":"حكم من أخذ مالًا مقابل عمل لم يقم به","answer":"الجواب: عليه التوبة إلى الله سبحانه، بالندم على الماضي، والعزم ألا يعود في ذلك، والله -جل وعلا- يقول سبحانه: وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى [طه:82] وعليه أن يتصدق بما يظن أنه لم يقابل عملًا منه، ويظنه زائدًا على حقه حسب ظنه، واجتهاده، يتصدق به في بعض الجهات الخيرية مثل الفقراء، مثل المجاهدين مثل إصلاح دورات المياه، إلى غير ذلك من وجوه الخير، حسب ما يظن... يتحرى المبلغ الذي لا يستحقه، فيتصدق به مع التوبة إلى الله والندم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15296/حكم-من-اخذ-مالا-مقابل-عمل-لم-يقم-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_816/nour_81610.mp3","categories":["أحكام الموظفين"]},{"id":16830,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع محمد صبري، أخونا له قضية يقول فيها: إنني أعمل مع أحد التجار، وهذا التاجر يعطيني المصروف يوميًا للمواصلات، وللأكل والشرب، لكنني لا أصرف ذلك المبلغ كله في الأكل والشرب، وإنما أصرف بعضه، والباقي أوفر منه، لكني أوفر على الوقت بحيث أستهلك وقتًا أطول.. أو فيما لو صرفت المبلغ كاملًا، وجهوني جزاكم الله خيرًا، هل ما أنا عليه صحيح، أو لا بد من اتباع ما طلب ذلكم التاجر؟ جزاكم الله خيرًا.","title":"حكم توفير العامل المصاريف بما بؤثر على العمل","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فإذا كنت متفقًا معه على مصرف معين، فأنت بالخيار تأكله كله، أو بعضه، لا حرج عليك، فقد طابت نفسه بذلك، وأنت أبصر بنفسك، تصرف الجميع، أو بعضه، نعم. المقدم: جزاكم الله خيرًا، يقول: إنه يؤثر على الوقت سماحة الشيخ بحيث يستهلك وقتًا أطول إذا لم يصرف المصروف كاملًا، ولاسيما في موضوع المواصلات كما يقول. الشيخ: إذا كان التقصير يؤثر على العمل؛ فلا يجوز لك، لا بد أن يكون العمل وافرًا كاملًا، فإذا كان عدم صرفك المصروف على وجه أكمل يؤثر على العمل، أو ينقص العمل؛ فلا يجوز لك، لا بد أن يكون العمل كاملًا كما شرط عليك كما اتفقتما، وعليك أن تصرف ما أعطيته إذا كان يعينك على العمل، ولا يحصل به تقصير، الحاصل أنه لا بد من إكمال العمل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15586/حكم-توفير-العامل-المصاريف-بما-بوثر-على-العمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_719/nour_71901.mp3","categories":["الإجارة","أحكام الموظفين"]},{"id":17090,"question":"من المستمع (ك. م. ع) من السودان رسالة ضمنها جمعًا من الأسئلة، في أحدها يقول: أنا أعمل مع أحد التجار، وهذا التاجر يدفع رشاوى حتى يسير عمله، علمًا بأنني أدير له أعماله الحسابية فقط، وأتقاضى على ذلك أجرًا، فهل يعتبر هذا المبلغ الذي آخذه حرام بالنسبة لي؟ أفيدونا أفادكم الله.","title":"حكم راتب من يعمل عند من يتعامل بالرشوة","answer":"الجواب: نرجو ألا يكون عليك شيء، والإثم عليه لما يدفع من الرشوة، الإثم عليه، وأنت -إن شاء الله- إذا كنت لا تعمل إلا ما أباح الله لا شيء عليك، لكن تنصحه، تنصحه وتحث إخوانك على نصيحته؛ لأن الرشوة حرام، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15943/حكم-راتب-من-يعمل-عند-من-يتعامل-بالرشوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_831/nour_83111.mp3","categories":["الإجارة","أحكام الموظفين"]},{"id":18378,"question":"السائل (ع. أ. م) يقول: بأنه يعمل عند أحد المقاولين بمهنة محاسب، ولكنني - يقول - علمت أن ماله فيه شيء من المكاسب المختلطة من الحرام والحلال، فهل ما آخذه منه كأجر مقابل عملي الذي أؤديه على الوجه المطلوب يشوبه شيء من ذلك الحرام أم لا؟وجزاكم الله خيرًا.","title":"حكم راتب العمل المختلط كسبه بين حلال وحرام","answer":"الجواب: إذا كان مال الرجل مختلطًا فلا حرج على من أكل من ماله وقت الوليمة، أو عامله في أي معاملة، لا حرج في ذلك؛ لأنه ثبت عن النبي ﷺ أنه اشترى من يهودي طعامًا ورهنه درعه، والله سبحانه حل لنا طعام أهل الكتاب وهم يتعاطون الربا .. أموالهم مختلطة، ومع هذا أحل الله لنا طعامهم كما قال جل وعلا: الْيَوْمَ أُحِلَّ لَكُمُ الطَّيِّبَاتُ وَطَعَامُ الَّذِينَ أُوتُوا الْكِتَابَ حِلٌّ لَكُمْ وَطَعَامُكُمْ حِلٌّ لَهُمْ[المائدة:5] وأهل الكتاب هم اليهود والنصارى وفي طعامهم ما فيه من الربا وغيره. أما إذا علمت أن هذا المال كله حرام، وأن كسبه كله حرام؛ فلا تأكل من كسبه من ماله، من طعامه إذا علمت أن كل كسبه حرام، أما إذا كان المال مخلوط عنده كسب جيد، وعنده كسب رديء؛ فلا حرج في الأكل من طعامه. نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17443/حكم-راتب-العمل-المختلط-كسبه-بين-حلال-وحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_784/nour_78403.mp3","categories":["أحكام الموظفين"]},{"id":18380,"question":"السائل (ع. أ. م) يقول: بأنه يعمل عند أحد المقاولين بمهنة محاسب، ولكنني - يقول - علمت أن ماله فيه شيء من المكاسب المختلطة من الحرام والحلال، فهل ما آخذه منه كأجر مقابل عملي الذي أؤديه على الوجه المطلوب يشوبه شيء من ذلك الحرام أم لا؟وجزاكم الله خيرًا.","title":"حكم راتب العمل المختلط كسبه بين حلال وحرام","answer":"الجواب: إذا كان مال الرجل مختلطًا فلا حرج على من أكل من ماله وقت الوليمة، أو عامله في أي معاملة، لا حرج في ذلك؛ لأنه ثبت عن النبي ﷺ أنه اشترى من يهودي طعامًا ورهنه درعه، والله سبحانه حل لنا طعام أهل الكتاب وهم يتعاطون الربا .. أموالهم مختلطة، ومع هذا أحل الله لنا طعامهم كما قال جل وعلا: الْيَوْمَ أُحِلَّ لَكُمُ الطَّيِّبَاتُ وَطَعَامُ الَّذِينَ أُوتُوا الْكِتَابَ حِلٌّ لَكُمْ وَطَعَامُكُمْ حِلٌّ لَهُمْ[المائدة:5] وأهل الكتاب هم اليهود والنصارى وفي طعامهم ما فيه من الربا وغيره. أما إذا علمت أن هذا المال كله حرام، وأن كسبه كله حرام؛ فلا تأكل من كسبه من ماله، من طعامه إذا علمت أن كل كسبه حرام، أما إذا كان المال مخلوط عنده كسب جيد، وعنده كسب رديء؛ فلا حرج في الأكل من طعامه. نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17443/حكم-راتب-العمل-المختلط-كسبه-بين-حلال-وحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_784/nour_78403.mp3","categories":["أحكام الموظفين"]}]
